<script setup lang="ts">
import {ShieldAlert,ArrowLeft,Download} from 'lucide-vue-next'
import {RELEASE_GATES,assessReleaseEvidence} from '~/utils/releaseDecision.mjs'
const authorized=ref(false),checked=ref(false),error=ref('')
onMounted(async()=>{try{const c=useSupabaseBrowser();if(!c)throw Error('Authentication unavailable');const {data:{user}}=await c.auth.getUser();if(!user){await navigateTo('/admin/login');return}const {data:admin,error:lookupError}=await c.from('admins').select('user_id').eq('user_id',user.id).maybeSingle();if(lookupError)throw lookupError;authorized.value=!!admin}catch(e:any){error.value=e?.message||'Access could not be verified'}finally{checked.value=true}})
const records=reactive<Record<string,{status:string;reference:string;notes:string}>>({})
const entry=(id:string)=>records[id]??(records[id]={status:'unverified',reference:'',notes:''})
const review=computed(()=>assessReleaseEvidence(records))
const exportReport=()=>{
 const report={site:'Norrli Pets',generatedAt:new Date().toISOString(),...review.value,entries:RELEASE_GATES.map(g=>({...g,...entry(g.id)}))}
 const url=URL.createObjectURL(new Blob([JSON.stringify(report,null,2)],{type:'application/json'}))
 const anchor=document.createElement('a');anchor.href=url;anchor.download='norrli-go-no-go-review.json';anchor.click();URL.revokeObjectURL(url)
}
useSeoMeta({title:'Final release decision review',robots:'noindex,nofollow'})
</script>
<template><main v-if="authorized" class="admin-shell"><header class="admin-topbar"><NorrliLogo compact/><NuxtLink to="/admin/production-audit" class="btn btn-secondary compact"><ArrowLeft :size="16"/> Production audit</NuxtLink></header><section class="release-wrap">
<span class="eyebrow"><ShieldAlert :size="16"/> PHASE 8.5 · RELEASE DECISION</span><h1>Go / No-Go Review</h1><p>Record the location of independent evidence, outstanding risks and reviewer notes. Entries stay in this page only until you export them; they never approve a product, payment integration or launch.</p>
<div class="release-alert" role="status"><ShieldAlert :size="21"/><div><strong>NO-GO — COMMERCIAL RELEASE NOT APPROVED</strong><p>{{review.outstanding.length}} of {{RELEASE_GATES.length}} evidence areas have missing verification or references. Even a complete checklist requires independent authorization and a separate release process.</p></div></div>
<div class="release-grid"><article v-for="gate in RELEASE_GATES" :key="gate.id"><div class="release-head"><strong>{{gate.label}}</strong><span>{{gate.priority}}</span></div><label>Review outcome<select v-model="entry(gate.id).status"><option value="unverified">Not verified</option><option value="verified">Verified (manual assertion)</option><option value="blocked">Blocked</option></select></label><label>Evidence reference<input v-model.trim="entry(gate.id).reference" maxlength="350" placeholder="Document or test-report reference"/></label><label>Reviewer notes<textarea v-model="entry(gate.id).notes" rows="2" maxlength="1500" placeholder="Scope, reviewer, date and remaining risks"/></label></article></div>
<button type="button" class="btn btn-secondary" @click="exportReport"><Download :size="17"/> Export review (JSON)</button><p>For audit use only: no payment activation, automatic email, supplier order, Merchant Center publication or product launch is triggered.</p>
</section></main><section v-else class="release-wrap" role="status">{{checked?'Administrator access required. '+error:'Checking administrator access…'}}</section></template>
<style scoped>.release-wrap{max-width:1060px;margin:36px auto;padding:0 20px 64px}.release-wrap h1{font:500 clamp(32px,4vw,50px) Georgia,serif;color:#254e37}.release-wrap>p{line-height:1.7;color:#627665}.release-alert{display:flex;gap:13px;padding:20px;border:1px solid #e3c6b5;border-radius:15px;background:#fbf2eb;color:#8b4433;margin:22px 0}.release-alert p{font-size:13px;line-height:1.65}.release-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px;margin:22px 0}.release-grid article{padding:20px;background:white;border:1px solid #dce6d7;border-radius:16px}.release-head{display:flex;gap:10px;justify-content:space-between;align-items:center;color:#254e37;margin-bottom:14px}.release-head span{color:#a45742;font-weight:800;font-size:12px}.release-grid label{display:grid;gap:5px;margin-top:12px;font-size:12px;color:#48624d}.release-grid :is(input,select,textarea){width:100%;border:1px solid #bfcfc0;border-radius:10px;padding:11px;background:#fff}.release-grid :is(input,select,textarea):focus-visible{outline:3px solid #377e57;outline-offset:2px}@media(max-width:720px){.release-grid{grid-template-columns:1fr}}</style>